import { frameIdFromRef } from './frames';
import type { A11ySnapshot, ToolCall } from './types';

export const BATCH_MIN_ACTIONS = 2;
export const BATCH_MAX_ACTIONS = 5;

const BATCHABLE_NAMES = new Set<ToolCall['name']>(['click', 'type', 'press', 'select']);
const SAFE_CLICK_ROLES = new Set(['button', 'checkbox', 'radio', 'switch', 'tab']);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function parseBatchActions(call: ToolCall): ToolCall[] {
  if (call.name !== 'batch_actions' || !Array.isArray(call.arguments.actions)) return [];
  return call.arguments.actions.flatMap((raw): ToolCall[] => {
    if (!isRecord(raw) || typeof raw.name !== 'string') return [];
    const nestedArgs = isRecord(raw.arguments) ? raw.arguments : undefined;
    const argumentsValue = nestedArgs ?? Object.fromEntries(
      Object.entries(raw).filter(([key]) => key !== 'name' && key !== 'arguments'),
    );
    return [{ name: raw.name as ToolCall['name'], arguments: argumentsValue }];
  });
}

export function batchPrimaryRef(call: ToolCall): string {
  return parseBatchActions(call)
    .map((action) => String(action.arguments.ref ?? ''))
    .find(Boolean) ?? '';
}

export function validateBatchCall(
  call: ToolCall,
  snapshot?: Pick<A11ySnapshot, 'nodes'>,
  confirmKeywords: string[] = [],
): string | undefined {
  if (call.name !== 'batch_actions') return undefined;
  if (!Array.isArray(call.arguments.actions)) return 'batch_actions requires an actions array';

  const actions = parseBatchActions(call);
  if (actions.length !== call.arguments.actions.length) return 'Every batch item must be an object with a valid name';
  if (actions.length < BATCH_MIN_ACTIONS || actions.length > BATCH_MAX_ACTIONS) {
    return `batch_actions requires ${BATCH_MIN_ACTIONS}-${BATCH_MAX_ACTIONS} actions`;
  }

  const frameIds = new Set<number>();
  for (const [index, action] of actions.entries()) {
    if (!BATCHABLE_NAMES.has(action.name)) return `Action ${index + 1} uses forbidden tool ${action.name}`;

    const ref = typeof action.arguments.ref === 'string' ? action.arguments.ref : '';
    if (action.name !== 'press' && !ref) return `Action ${index + 1} (${action.name}) requires ref`;
    if (ref) {
      frameIds.add(frameIdFromRef(ref));
      const node = snapshot?.nodes.find((candidate) => candidate.ref === ref);
      if (snapshot && !node) return `Action ${index + 1} references missing element ${ref}`;
      if (action.name === 'click' && node && (!SAFE_CLICK_ROLES.has(node.role) || node.href)) {
        return `Action ${index + 1} cannot batch click ${node.role} ${ref}; links and navigation-like targets must run separately`;
      }
      if (node) {
        const label = `${node.name} ${node.value ?? ''}`.toLowerCase();
        if (confirmKeywords.some((keyword) => keyword && label.includes(keyword.toLowerCase()))) {
          return `Action ${index + 1} targets a confirmation-sensitive control and must run separately`;
        }
      }
    }

    if (action.name === 'type') {
      if (typeof action.arguments.text !== 'string') return `Action ${index + 1} (type) requires text`;
      if (String(action.arguments.submit ?? 'false') === 'true') return `Action ${index + 1} cannot submit from a batch`;
    }
    if (action.name === 'select' && typeof action.arguments.value !== 'string') {
      return `Action ${index + 1} (select) requires value`;
    }
    if (action.name === 'press') {
      const key = String(action.arguments.key ?? '').trim();
      if (!key) return `Action ${index + 1} (press) requires key`;
      if (key.toLowerCase() === 'enter') return `Action ${index + 1} cannot press Enter from a batch`;
    }
  }

  if (frameIds.size > 1) return 'All batched actions must target the same frame';
  return undefined;
}

/**
 * A read-only tool can report ok:true and still have brought back nothing usable — an empty
 * array of refs, a body-text fallback on an interstitial that only holds a script call. The
 * loop treats "the action ran" and "the data arrived" as the same thing unless something
 * separates them here, so every extract keeps looking like progress.
 */

/** Body-text fallback shorter than this is a placeholder page, not page content. */
const MIN_BODY_FALLBACK_CHARS = 40;

const BODY_FALLBACK_REF = 'document.body';

export interface ExtractionOptions {
  /**
   * The page the payload came from exposes no accessibility nodes and no text. Nothing readable
   * exists there, so a whole-body fallback is a placeholder no matter how long it is.
   */
  pageIsBlank?: boolean;
}

export interface ExtractionSummary {
  /** True when the payload carries content the task can actually use. */
  hasData: boolean;
  /** Items that carry text, a value, or an href. */
  itemCount: number;
  /** Why the payload does not count as data — worded for the model. */
  reason?: string;
}

export function summarizeExtraction(extracted: unknown, options: ExtractionOptions = {}): ExtractionSummary {
  if (extracted === undefined || extracted === null) {
    return { hasData: false, itemCount: 0, reason: 'the tool returned no payload at all' };
  }

  if (typeof extracted === 'string') {
    const text = extracted.trim();
    return text
      ? { hasData: true, itemCount: 1 }
      : { hasData: false, itemCount: 0, reason: 'the returned text was empty' };
  }

  if (Array.isArray(extracted)) {
    return summarizeItems(extracted, options);
  }

  if (typeof extracted === 'object') {
    const cells = (extracted as { cells?: unknown }).cells;
    if (Array.isArray(cells)) {
      const rows = cells.filter((row) => Array.isArray(row) && row.some((cell) => String(cell ?? '').trim()));
      return rows.length > 0
        ? { hasData: true, itemCount: rows.length }
        : { hasData: false, itemCount: 0, reason: 'the range came back with no non-empty cells' };
    }
    return Object.keys(extracted as Record<string, unknown>).length > 0
      ? { hasData: true, itemCount: 1 }
      : { hasData: false, itemCount: 0, reason: 'the returned object was empty' };
  }

  return { hasData: true, itemCount: 1 };
}

function summarizeItems(items: unknown[], options: ExtractionOptions): ExtractionSummary {
  const filled = items.filter(itemHasContent);
  if (filled.length === 0) {
    return {
      hasData: false,
      itemCount: 0,
      reason: items.length === 0
        ? 'the tool returned zero items'
        : `all ${items.length} returned items were empty`,
    };
  }

  // Only the whole-body fallback came back. On a page with no accessibility tree that is a
  // placeholder — an interstitial's bootstrap script, a document caught mid-navigation — and
  // even on a normal page a fallback this short carries nothing worth reporting.
  const onlyBodyFallback = filled.every((item) => itemRef(item) === BODY_FALLBACK_REF);
  if (onlyBodyFallback) {
    const chars = filled.reduce<number>((total, item) => total + itemText(item).length, 0);
    if (options.pageIsBlank) {
      return {
        hasData: false,
        itemCount: 0,
        reason: `only a body-text fallback came back (${chars} characters) from a page that exposes no accessibility nodes, so this is placeholder text rather than page content`,
      };
    }
    if (chars < MIN_BODY_FALLBACK_CHARS) {
      return {
        hasData: false,
        itemCount: 0,
        reason: `only a ${chars}-character body-text fallback came back, so the page has no readable content yet`,
      };
    }
  }

  return { hasData: true, itemCount: filled.length };
}

function itemHasContent(item: unknown): boolean {
  if (typeof item === 'string') return item.trim().length > 0;
  if (!item || typeof item !== 'object') return false;
  const record = item as Record<string, unknown>;
  return Boolean(
    itemText(record) || String(record.value ?? '').trim() || String(record.href ?? '').trim(),
  );
}

function itemText(item: unknown): string {
  if (typeof item === 'string') return item.trim();
  if (!item || typeof item !== 'object') return '';
  return String((item as Record<string, unknown>).text ?? '').trim();
}

function itemRef(item: unknown): string {
  if (!item || typeof item !== 'object') return '';
  return String((item as Record<string, unknown>).ref ?? '');
}

import type { ActionResult, ToolCall } from './types';
import { findElementByRef } from './a11y';
import { parseBatchActions, validateBatchCall } from './batch-actions';

interface BatchActionOutcome {
  index: number;
  name: ToolCall['name'];
  ok: boolean;
  error?: string;
}

class BatchActionError extends Error {
  constructor(message: string, readonly outcomes: BatchActionOutcome[]) {
    super(message);
  }
}

export async function runAction(call: ToolCall, timeoutMs: number): Promise<ActionResult> {
  const start = performance.now();
  try {
    const result = await withTimeout(dispatch(call), timeoutMs);
    return { ok: true, durationMs: performance.now() - start, ...(result ? { extracted: result } : {}) };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : String(err),
      durationMs: performance.now() - start,
      ...(err instanceof BatchActionError ? { extracted: { outcomes: err.outcomes, stoppedAt: err.outcomes.length } } : {}),
    };
  }
}

async function dispatch(call: ToolCall): Promise<unknown> {
  switch (call.name) {
    case 'set_task_plan':
      return undefined;
    case 'batch_actions': return doBatchActions(call);
    case 'click': return doClick(String(call.arguments.ref ?? ''));
    case 'type': return doType(
      String(call.arguments.ref ?? ''),
      String(call.arguments.text ?? ''),
      String(call.arguments.mode ?? 'replace') === 'append' ? 'append' : 'replace',
      String(call.arguments.submit ?? 'false') === 'true',
    );
    case 'press': return doPress(
      String(call.arguments.key ?? ''),
      String(call.arguments.modifiers ?? ''),
      call.arguments.ref ? String(call.arguments.ref) : undefined,
    );
    case 'select': return doSelect(String(call.arguments.ref ?? ''), String(call.arguments.value ?? ''));
    case 'scroll': return doScroll(
      String(call.arguments.direction ?? 'down'),
      call.arguments.ref ? String(call.arguments.ref) : undefined,
      typeof call.arguments.amountPx === 'number' ? call.arguments.amountPx : 400,
    );
    case 'wait': return doWait(
      Math.min(Number(call.arguments.ms ?? 1000), 10_000),
      String(call.arguments.until ?? 'none'),
      call.arguments.ref ? String(call.arguments.ref) : undefined,
    );
    case 'extract': return doExtract(String(call.arguments.refs ?? ''));
    case 'navigate':
    case 'done':
    case 'open_tab':
    case 'switch_tab':
    case 'list_tabs':
    case 'close_tabs':
    case 'bookmark_tabs':
    case 'group_tabs':
    case 'ungroup_tabs':
    case 'paste_table':
    case 'fill_cells':
    case 'select_cell':
    case 'set_cell':
    case 'read_cells':
    case 'define_sheet_contract':
    case 'fill_login_credentials':
    case 'solve_captcha':
    case 'read_downloaded_file':
    case 'upload_attachment':
    case 'start_subtask':
    case 'finish_subtask':
    case 'fail_subtask':
    case 'update_task_memory':

      return undefined;

    default:
      throw new Error(`Unknown action: ${(call as { name: string }).name}`);
  }
}

async function doBatchActions(call: ToolCall): Promise<{ outcomes: BatchActionOutcome[]; completed: number }> {
  const validationError = validateBatchCall(call);
  if (validationError) throw new BatchActionError(validationError, []);

  const outcomes: BatchActionOutcome[] = [];
  for (const [index, action] of parseBatchActions(call).entries()) {
    try {
      await dispatch(action);
      outcomes.push({ index, name: action.name, ok: true });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      outcomes.push({ index, name: action.name, ok: false, error: message });
      throw new BatchActionError(`Batch stopped at action ${index + 1} (${action.name}): ${message}`, outcomes);
    }
  }
  return { outcomes, completed: outcomes.length };
}

function resolve(ref: string): HTMLElement {
  const el = findElementByRef(ref);
  if (!el) throw new Error(`Element ${ref} not found in current snapshot`);
  el.scrollIntoView({ block: 'center', behavior: 'instant' as ScrollBehavior });
  return el;
}

async function doClick(ref: string): Promise<void> {
  const el = resolve(ref);
  const event = new MouseEvent('click', { bubbles: true, cancelable: true, view: window });
  const dispatched = el.dispatchEvent(event);
  if (!dispatched) throw new Error('Click was cancelled by page');
  await tick();
}

async function doType(ref: string, text: string, mode: 'replace' | 'append', submit: boolean): Promise<void> {
  const el = resolve(ref);
  if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
    el.focus();
    const proto = el instanceof HTMLInputElement ? HTMLInputElement.prototype : HTMLTextAreaElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
    if (mode === 'replace') {
      el.dispatchEvent(new InputEvent('beforeinput', { bubbles: true, cancelable: true, inputType: 'deleteContentBackward' }));
      setter?.call(el, '');
      el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'deleteContentBackward' }));
    }
    el.dispatchEvent(new InputEvent('beforeinput', { bubbles: true, cancelable: true, inputType: 'insertText', data: text }));
    setter?.call(el, mode === 'append' ? `${el.value}${text}` : text);
    el.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: text }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    el.dispatchEvent(new FocusEvent('focusout', { bubbles: true }));
    el.dispatchEvent(new FocusEvent('blur', { bubbles: false }));
    if (submit) {
      el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', bubbles: true }));
      el.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', code: 'Enter', bubbles: true }));
      const form = el.closest('form');
      form?.requestSubmit?.();
    }
    return;
  }
  const editable = resolveContentEditable(el);
  if (editable) {
    editable.focus();
    if (mode === 'replace') {
      const sel = window.getSelection();
      const range = document.createRange();
      range.selectNodeContents(editable);
      sel?.removeAllRanges();
      sel?.addRange(range);
      document.execCommand('delete', false);
    }
    const inserted = document.execCommand('insertText', false, text);
    if (!inserted) {
      if (mode === 'replace') {
        editable.textContent = text;
      } else {
        editable.textContent = `${editable.textContent ?? ''}${text}`;
      }
    }
    editable.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: text }));
    editable.dispatchEvent(new Event('change', { bubbles: true }));
    if (submit) {
      editable.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', bubbles: true }));
      editable.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', code: 'Enter', bubbles: true }));
      const form = editable.closest('form');
      form?.requestSubmit?.();
    }
    return;
  }
  throw new Error(`Element ${ref} is not a text input`);
}


async function doPress(key: string, modifiersText: string, ref?: string): Promise<void> {
  const target = ref ? resolve(ref) : activeTarget();
  target.focus();
  const modifiers = parseModifiers(modifiersText);
  const normalizedKey = normalizeKey(key);

  if ((modifiers.metaKey || modifiers.ctrlKey) && !modifiers.shiftKey && !modifiers.altKey) {
    const command = shortcutCommand(normalizedKey);
    if (command) {
      document.execCommand(command, false);
      dispatchEditorInput(activeTarget());
      await tick();
      return;
    }
  }

  dispatchKey(target, 'keydown', normalizedKey, modifiers);
  if (normalizedKey === 'Enter' && activeTarget().isContentEditable) {
    document.execCommand('insertParagraph', false);
    dispatchEditorInput(activeTarget());
  }
  dispatchKey(target, 'keyup', normalizedKey, modifiers);
  await tick();
}

function resolveContentEditable(el: HTMLElement): HTMLElement | null {
  if (el.isContentEditable) return el;
  const child = el.querySelector<HTMLElement>('[contenteditable="true"]');
  if (child?.isContentEditable) return child;
  const parent = el.closest<HTMLElement>('[contenteditable="true"]');
  return parent?.isContentEditable ? parent : null;
}

function activeTarget(): HTMLElement {
  return document.activeElement instanceof HTMLElement ? document.activeElement : document.body;
}

function parseModifiers(value: string): Pick<KeyboardEventInit, 'altKey' | 'ctrlKey' | 'metaKey' | 'shiftKey'> {
  const parts = value.toLowerCase().split(/[\s,+]+/).filter(Boolean);
  return {
    altKey: parts.includes('alt') || parts.includes('option'),
    ctrlKey: parts.includes('ctrl') || parts.includes('control'),
    metaKey: parts.includes('meta') || parts.includes('cmd') || parts.includes('command'),
    shiftKey: parts.includes('shift'),
  };
}

function normalizeKey(key: string): string {
  const trimmed = key.trim();
  if (!trimmed) throw new Error('press requires key');
  if (trimmed.length === 1) return trimmed.toLowerCase();
  return trimmed;
}

function shortcutCommand(key: string): string | null {
  switch (key.toLowerCase()) {
    case 'b': return 'bold';
    case 'i': return 'italic';
    case 'u': return 'underline';
    default: return null;
  }
}

function dispatchKey(target: HTMLElement, type: 'keydown' | 'keyup', key: string, modifiers: KeyboardEventInit): void {
  target.dispatchEvent(new KeyboardEvent(type, {
    bubbles: true,
    cancelable: true,
    key,
    code: key.length === 1 ? `Key${key.toUpperCase()}` : key,
    ...modifiers,
  }));
}

function dispatchEditorInput(target: HTMLElement, data?: string): void {
  target.dispatchEvent(new InputEvent('input', {
    bubbles: true,
    inputType: 'insertText',
    data,
  }));
  target.dispatchEvent(new Event('change', { bubbles: true }));
}

async function doSelect(ref: string, value: string): Promise<void> {
  const el = resolve(ref);
  if (!(el instanceof HTMLSelectElement)) throw new Error(`Element ${ref} is not a <select>`);
  const lowerVal = value.trim().toLowerCase();
  const match = Array.from(el.options).find(
    (o) =>
      o.value === value ||
      o.textContent?.trim() === value.trim() ||
      o.value.toLowerCase() === lowerVal ||
      o.textContent?.trim().toLowerCase() === lowerVal,
  );
  if (!match) throw new Error(`Option "${value}" not found`);
  el.value = match.value;
  el.dispatchEvent(new Event('input', { bubbles: true }));
  el.dispatchEvent(new Event('change', { bubbles: true }));
}

function findScrollableContainer(target?: HTMLElement | null): HTMLElement | null {
  let curr = target ?? (document.activeElement instanceof HTMLElement ? document.activeElement : null);
  while (curr && curr !== document.body && curr !== document.documentElement) {
    try {
      const style = window.getComputedStyle(curr);
      const overflowY = style.overflowY;
      const isScrollable = (overflowY === 'auto' || overflowY === 'scroll' || overflowY === 'overlay') &&
        curr.scrollHeight > curr.clientHeight + 10;
      if (isScrollable) return curr;
    } catch {
      // Ignore if disconnected
    }
    curr = curr.parentElement;
  }
  return null;
}

async function doScroll(
  direction: string,
  ref: string | undefined,
  amountPx: number,
): Promise<{ scrolled: boolean; scrollY: number; atBoundary: boolean; note?: string }> {
  let container: HTMLElement | null = null;
  if (ref) {
    const el = findElementByRef(ref);
    if (el instanceof HTMLElement) {
      container = findScrollableContainer(el) ?? el;
    }
  } else {
    container = findScrollableContainer();
  }

  const isContainer = Boolean(container && container !== document.body && container !== document.documentElement);
  const beforeY = isContainer && container ? container.scrollTop : window.scrollY;
  const maxScrollY = isContainer && container
    ? Math.max(0, container.scrollHeight - container.clientHeight)
    : Math.max(0, Math.max(document.documentElement.scrollHeight, document.body.scrollHeight) - window.innerHeight);

  if (isContainer && container) {
    switch (direction) {
      case 'up': container.scrollBy({ top: -amountPx, behavior: 'instant' as ScrollBehavior }); break;
      case 'down': container.scrollBy({ top: amountPx, behavior: 'instant' as ScrollBehavior }); break;
      case 'top': container.scrollTo({ top: 0, behavior: 'instant' as ScrollBehavior }); break;
      case 'bottom': container.scrollTo({ top: container.scrollHeight, behavior: 'instant' as ScrollBehavior }); break;
      case 'to_ref': {
        if (!ref) throw new Error('scroll to_ref requires ref');
        resolve(ref);
        break;
      }
      default: throw new Error(`Unknown direction: ${direction}`);
    }
  } else {
    switch (direction) {
      case 'up': window.scrollBy({ top: -amountPx, behavior: 'instant' as ScrollBehavior }); break;
      case 'down': window.scrollBy({ top: amountPx, behavior: 'instant' as ScrollBehavior }); break;
      case 'top': window.scrollTo({ top: 0, behavior: 'instant' as ScrollBehavior }); break;
      case 'bottom': window.scrollTo({ top: Math.max(document.body.scrollHeight, document.documentElement.scrollHeight), behavior: 'instant' as ScrollBehavior }); break;
      case 'to_ref': {
        if (!ref) throw new Error('scroll to_ref requires ref');
        resolve(ref);
        break;
      }
      default: throw new Error(`Unknown direction: ${direction}`);
    }
  }
  await tick();

  const afterY = isContainer && container ? container.scrollTop : window.scrollY;
  const delta = Math.abs(afterY - beforeY);
  const atBottom = afterY >= maxScrollY - 10;
  const atTop = afterY <= 10;
  const scrolled = delta > 2;

  let note: string | undefined;
  if (!scrolled && direction === 'down') {
    note = 'Page bottom reached or scroll position unchanged. Stop scrolling: extract what is visible, search, or navigate.';
  } else if (!scrolled && direction === 'up') {
    note = 'Page top reached or scroll position unchanged.';
  } else if (atBottom && direction === 'down') {
    note = 'Page bottom reached. All content on this page is now visible.';
  }

  return {
    scrolled,
    scrollY: Math.round(afterY),
    atBoundary: atBottom || atTop,
    ...(note ? { note } : {}),
  };
}

async function doWait(ms: number, until: string, ref?: string): Promise<void> {
  if (until === 'none') { await sleep(ms); return; }
  if (until === 'load') {
    if (document.readyState === 'complete') return;
    await new Promise<void>((resolve) => {
      const done = () => { window.removeEventListener('load', done); resolve(); };
      window.addEventListener('load', done, { once: true });
      setTimeout(done, ms);
    });
    return;
  }
  if (until === 'element') {
    if (!ref) throw new Error('wait until=element requires ref');
    const start = Date.now();
    while (Date.now() - start < ms) {
      if (findElementByRef(ref)) return;
      await sleep(100);
    }
    throw new Error(`Element ${ref} did not appear within ${ms}ms`);
  }
  if (until === 'network_idle') {
    await sleep(Math.min(ms, 2000));
    return;
  }
}

type ExtractedItem = { ref: string; text: string; value?: string; href?: string };

function doExtract(refs: string): ExtractedItem[] {
  const mode = refs.trim().toLowerCase();
  if (mode === 'visible') return extractVisibleText();
  if (mode === 'all') return [{ ref: 'document.body', text: normalizeText(document.body.innerText).slice(0, 12_000) }];

  return refs.split(',').map((r) => r.trim()).filter(Boolean).map((ref) => {
    const el = findElementByRef(ref);
    if (!el) return { ref, text: '' };
    const value = (el as HTMLInputElement).value;
    const href = el instanceof HTMLAnchorElement ? el.href : '';
    return { ref, text: normalizeText(el.textContent ?? ''), ...(value ? { value } : {}), ...(href ? { href } : {}) };
  });
}

function extractVisibleText(maxItems = 80): ExtractedItem[] {
  const selectors = [
    'h1', 'h2', 'h3', 'h4', 'p', 'li', 'dt', 'dd',
    'blockquote', 'figcaption', '[role="heading"]',
    '[data-attrid]', '[data-sncf]', '[aria-level]',
  ].join(',');
  const candidates: Array<ExtractedItem & { score: number; top: number }> = [];
  const seen = new Set<string>();
  const viewportW = window.innerWidth;
  const viewportH = window.innerHeight;

  for (const el of document.querySelectorAll<HTMLElement>(selectors)) {
    if (!isVisibleElement(el)) continue;
    const rect = el.getBoundingClientRect();
    const inViewport = rect.bottom > 0 && rect.right > 0 && rect.top < viewportH && rect.left < viewportW;
    if (!inViewport) continue;
    const text = normalizeText(el.textContent ?? '');
    if (!isUsefulText(text) || seen.has(text)) continue;
    seen.add(text);
    candidates.push({ ref: cssPath(el), text, score: scoreText(text, rect), top: rect.top });
  }

  if (candidates.length === 0) {
    const text = normalizeText(document.body.innerText);
    if (text) candidates.push({ ref: 'document.body', text: text.slice(0, 4_000), score: 0, top: 0 });
  }

  return candidates
    .sort((a, b) => b.score - a.score || a.top - b.top)
    .slice(0, maxItems)
    .map((item) => ({
      ref: item.ref,
      text: item.text,
      ...(item.value ? { value: item.value } : {}),
      ...(item.href ? { href: item.href } : {}),
    }));
}

function isVisibleElement(el: HTMLElement): boolean {
  if (el.hidden) return false;
  const style = window.getComputedStyle(el);
  if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return false;
  const rect = el.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0;
}

function normalizeText(text: string): string {
  return text.trim().replace(/\s+/g, ' ');
}

function isUsefulText(text: string): boolean {
  if (text.length < 8) return false;
  if (/^(todos?|all|videos?|im[aá]genes|web|noticias|m[aá]s|herramientas)$/i.test(text)) return false;
  if (/^(mostrar m[aá]s|vista creada con ia|m[aá]s preguntas)$/i.test(text)) return false;
  if (text.length > 1_200) return false;
  return true;
}

function scoreText(text: string, rect: DOMRect): number {
  let score = 0;
  if (/[А-Яа-яЁё]/.test(text)) score += 8;
  if (/правильно|пишется|русск|вариант|написани|официальн|разговорн|youtube|ютуб/i.test(text)) score += 8;
  if (/[.!?…:]$/.test(text)) score += 2;
  if (text.length >= 40 && text.length <= 500) score += 4;
  if (rect.top < window.innerHeight * 0.65) score += 2;
  return score;
}

function cssPath(el: HTMLElement): string {
  if (el.id) return `#${el.id}`;
  const tag = el.tagName.toLowerCase();
  const parent = el.parentElement;
  if (!parent) return tag;
  const siblings = Array.from(parent.children).filter((child) => child.tagName === el.tagName);
  if (siblings.length <= 1) return tag;
  return `${tag}:nth-of-type(${siblings.indexOf(el) + 1})`;
}

export function waitForSettledDom(maxWaitMs = 1200, quietMs = 100): Promise<void> {
  return new Promise((resolve) => {
    let timer: number | null = null;
    let maxTimeout: number | null = null;
    let observer: MutationObserver | null = null;

    const cleanup = () => {
      if (timer !== null) clearTimeout(timer);
      if (maxTimeout !== null) clearTimeout(maxTimeout);
      if (observer) observer.disconnect();
    };

    const done = () => {
      cleanup();
      resolve();
    };

    try {
      if (typeof MutationObserver !== 'undefined' && document?.documentElement) {
        observer = new MutationObserver(() => {
          if (timer !== null) clearTimeout(timer);
          timer = window.setTimeout(done, quietMs);
        });
        observer.observe(document.documentElement, {
          childList: true,
          subtree: true,
          attributes: true,
          characterData: true,
        });
      }
      timer = window.setTimeout(done, quietMs);
      maxTimeout = window.setTimeout(done, maxWaitMs);
    } catch {
      setTimeout(done, quietMs);
    }
  });
}

function tick(): Promise<void> { return waitForSettledDom(600, 50); }
function sleep(ms: number): Promise<void> { return new Promise((r) => setTimeout(r, ms)); }

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`Action timed out after ${ms}ms`)), ms);
    p.then(
      (v) => { clearTimeout(t); resolve(v); },
      (e) => { clearTimeout(t); reject(e); },
    );
  });
}

#!/usr/bin/env node
// WebOperator framed JSON client for agents.
const net = require('net');
const { randomUUID } = require('crypto');

const socketPath = process.env.WEBOPERATOR_AGENT_SOCKET || '/tmp/weboperator-bridge.sock';
const token = process.env.WEBOPERATOR_API_TOKEN || '';
const input = process.argv[2] ? JSON.parse(process.argv[2]) : { type: 'bridge.health' };
const message = {
  id: input.id || randomUUID(),
  type: input.type || 'bridge.health',
  payload: input.payload || {},
  timeoutMs: input.timeoutMs,
  ...(token ? { token } : {}),
};

let buffer = Buffer.alloc(0);
let nextFrameLength = null;
const socket = net.createConnection(socketPath, () => sendFrame(socket, message));

socket.on('data', (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  readFrames();
});
socket.on('error', (err) => {
  console.error(err.message);
  process.exitCode = 1;
});

function readFrames() {
  while (true) {
    if (nextFrameLength === null) {
      if (buffer.length < 4) return;
      nextFrameLength = buffer.readUInt32LE(0);
      buffer = buffer.slice(4);
    }
    if (buffer.length < nextFrameLength) return;
    const payload = buffer.slice(0, nextFrameLength).toString('utf8');
    buffer = buffer.slice(nextFrameLength);
    nextFrameLength = null;
    const msg = JSON.parse(payload);
    if (msg.kind === 'event') {
      console.error(JSON.stringify(msg));
      continue;
    }
    console.log(JSON.stringify(msg, null, 2));
    socket.end();
  }
}

function sendFrame(sock, obj) {
  const body = Buffer.from(JSON.stringify(obj), 'utf8');
  const header = Buffer.alloc(4);
  header.writeUInt32LE(body.length, 0);
  sock.write(Buffer.concat([header, body]));
}
